/* Strict event-significator PD admission and PD-bounded timing. */
(function(root){'use strict';const DAY=86400000;
function eventHouses(rule){return [...new Set([...(rule.relevantHouses||[]),...(rule.supportingGroups||[]).flat(),...(rule.mainHouses||[]),...(/^(?:1[0-2]|[1-9])(?:\s*,\s*(?:1[0-2]|[1-9]))*$/.test(rule.timingRaw||'')?rule.timingRaw.split(',').map(Number):[])])].filter(h=>Number.isInteger(h)&&h>=1&&h<=12);}
function houses(model,id){const collect=code=>{const row=model.fourfold?.planets?.find(p=>p.id===code);return ['A','B','C','D'].flatMap(k=>row?.[k]||[]);},own=collect(id);if(['Ra','Ke'].includes(id)){const point=model.planets?.find(p=>p.id===id),index=Number.isInteger(point?.signIndex)?point.signIndex:Number.isFinite(point?.longitude)?Math.floor(((point.longitude%1296000)+1296000)%1296000/108000):null,lord=index===null?point?.sgl:['Ma','Ve','Me','Mo','Su','Me','Ve','Ma','Ju','Sa','Sa','Ju'][index];if(lord&&lord!==id)own.push(...collect(lord));}return [...new Set(own)].filter(h=>Number.isInteger(h)&&h>=1&&h<=12).sort((a,b)=>a-b);}
function significators(model,rule){const wanted=eventHouses(rule);return (model.fourfold?.planets||[]).filter(p=>houses(model,p.id).some(h=>wanted.includes(h))).map(p=>p.id);}
function eligible(rows,ids,code=id=>id){const allowed=new Set(ids);return rows.filter(p=>p.matched&&allowed.has(code(p.lord)));}
function clip(rows,pd,offset){if(!pd)return [];const a=pd.startMs-offset*3600000,b=pd.endMs-offset*3600000;return rows.flatMap(r=>{const start=Math.max(Date.parse(r.start),a),end=Math.min(Date.parse(r.end),b);return end>start?[{...r,start:new Date(start).toISOString(),end:new Date(end).toISOString(),startClipped:!!r.startClipped||start>Date.parse(r.start),endClipped:!!r.endClipped||end<Date.parse(r.end)}]:[];});}
function track(pd,planet,rule,ids,signs){const allowed=new Set(ids);if(!allowed.has(pd))throw Error('Selected PD lord is not an event significator.');if(!['Su','Mo','As'].includes(planet))throw Error('Choose Sun, Moon or Lagna.');if(!['sub','star','sign'].includes(rule))throw Error('Choose a valid PD transit rule.');const test=rule==='sub'?p=>allowed.has(p.stl)&&p.sl===pd:rule==='star'?p=>p.stl===pd&&allowed.has(p.sl):p=>signs.includes(p.signIndex)&&allowed.has(p.stl)&&allowed.has(p.sl);return {id:'pd:'+pd+':'+planet+':'+rule,planet,label:({Su:'Sun',Mo:'Moon',As:'Lagna'})[planet]+' · PD '+pd+' · '+({sub:'event-significator star + PD sub',star:'PD nakshatra + event-significator sub',sign:'PD Rashi + event-significator star/sub'})[rule],levels:rule==='sign'?['sign','star','sub']:['star','sub'],test};}
async function refine({pd,offset,id,planet='Su',rule='sub',significators,signs=[],location,scan,cancelled=()=>false,progress=()=>{}}){if(!pd)return [];const t=track(id,planet,rule,significators,signs),start=pd.startMs-offset*3600000,end=pd.endMs-offset*3600000;if(!(end>start))throw Error('Selected PD has no valid interval.');const step=planet==='As'?2*DAY:end-start,found=[];for(let a=start;a<end;a+=step){if(cancelled())throw Error('Search cancelled.');const b=Math.min(a+step,end),rows=await scan({start:new Date(a),end:new Date(b),tracks:[t],location,shouldCancel:cancelled,onProgress:p=>progress((a-start+(b-a)*p)/(end-start))});if(cancelled())throw Error('Search cancelled.');for(const r of rows){const lo=Math.max(a,Date.parse(r.start)),hi=Math.min(b,Date.parse(r.end));if(hi>lo){const next={...r,start:new Date(lo).toISOString(),end:new Date(hi).toISOString(),pd:id,pdStart:new Date(start).toISOString(),pdEnd:new Date(end).toISOString()},prev=found.at(-1);if(prev&&prev.trackId===next.trackId&&prev.end===next.start&&prev.endClipped&&next.startClipped){prev.end=next.end;prev.endClipped=next.endClipped;}else found.push(next);}}if(found.length>20000)throw Error('More than 20,000 refinement intervals. Select a shorter PD or another timing planet.');progress((b-start)/(end-start));}return found;}
root.KPPDTransit=Object.freeze({eventHouses,houses,significators,eligible,clip,track,refine});
})(globalThis);
